var MouseDown = function (e, ctx) {
  ctx.moveTo(e.x, e.y);
  console.log("MOUSE DOWN");
};
var MouseMoveRect = function (e, ctx) {
  ctx.moveTo(e.x, e.y);
  console.log("MOUSE MOVING");
};

export { MouseDown, MouseMoveRect };
